+import { DatabaseClient } from '../db/DatabaseClient.js';
+import { Config } from '../config/Config.js';
+
+const C = {
+  reset: '\x1b[0m',
+  bright: '\x1b[1m',
+  red: '\x1b[31m',
+  green: '\x1b[32m',
+  yellow: '\x1b[33m',
+  cyan: '\x1b[36m',
+  gray: '\x1b[90m',
+};
+
+interface Issue {
+  id: string;
+  title: string;
+  description: string;
+  issue_type: string;
+  severity: string;
+  status: string;
+  discovered_by: string;
+  discovered_at: Date;
+  resolution: string | null;
+  resolved_at: Date | null;
+  resolved_by: string | null;
+  tags: string[];
+  created_at: Date;
+  updated_at: Date;
